/**
 * Referral codes: 8 lowercase letters/digits, generated by the database
 * (migration 0013). Pure and client-safe, so the sign-up carry can read them.
 */
const CODE = /^[a-z0-9]{8}$/;

/** A well-formed code from user input (case-insensitive), or null. */
export function normalizeReferralCode(raw: string | null | undefined): string | null {
  const code = raw?.trim().toLowerCase();
  return code && CODE.test(code) ? code : null;
}

/** The link a creator shares: `/r/<code>` opens sign-up with the code carried. */
export const REFERRAL_PATH_PREFIX = '/r/';

export const referralLink = (origin: string, code: string): string =>
  `${origin.replace(/\/+$/, '')}${REFERRAL_PATH_PREFIX}${code}`;
